bmql-safe.syntax:
// bmql-safe: parameterized query with null-guard
${1:rows} = bmql("SELECT ${2:col1}, ${3:col2} FROM ${4:table_name} WHERE ${5:field} = '$${6:param}'", ${6:param});
if (isnull(${1:rows}) or sizeofarray(${1:rows}) == 0) {
	${7:// handle empty result}
	return "";
}
${8:val} = ${1:rows}[0].${2:col1};

examples:
rows = bmql("SELECT price FROM products WHERE sku = '$sku'", sku);
if (isnull(rows) or sizeofarray(rows) == 0) {
	return "0.0";
}
return rows[0].price;

bmql-loop.syntax:
// bmql-loop: query result iteration
${1:rows} = bmql("SELECT ${2:col} FROM ${3:table}");
if (not(isnull(${1:rows})) and sizeofarray(${1:rows}) > 0) {
	for ${4:row} in ${1:rows} {
		${5:val} = ${4:row}.${2:col};
		${6:// process val}
	}
}

examples:
rows = bmql("SELECT name, price FROM products");
if (not(isnull(rows)) and sizeofarray(rows) > 0) {
	for row in rows {
		name = row.name;
		price = row.price;
	}
}

sb-concat.syntax:
// sb-concat: StringBuilder pattern for efficient string accumulation
${1:sb} = stringbuilder();
for ${2:item} in ${3:arr} {
	sbappend(${1:sb}, ${2:item});
	sbappend(${1:sb}, "${4:,}");
}
${5:result} = sbtostring(${1:sb});

examples:
sb = stringbuilder();
for item in myArray {
	sbappend(sb, item);
	sbappend(sb, ",");
}
result = sbtostring(sb);
return result;

null-guard.syntax:
if (isnull(${1:var}) or trim(${1:var}) == "") {
	${2:// handle null/empty}
	return ${3:""};
}

split-safe.syntax:
// split-safe: split with array boundary check
${1:parts} = split(${2:inputStr}, "${3:,}");
if (sizeofarray(${1:parts}) > ${4:0}) {
	${5:first} = ${1:parts}[0];
}

