try-atoi.syntax:
// try-atoi: safe integer conversion
if (isnumber(${1:strVal})) {
	${2:numVal} = atoi(${1:strVal});
} else {
	${3:// handle non-numeric}
	${2:numVal} = ${4:0};
}
